#include <string>
#include <vector>
#include <unordered_set>

class Solution {
public:
    bool possiblyEquals(std::string s1, std::string s2) {
        int n1 = s1.size(), n2 = s2.size();
        std::vector<std::vector<std::unordered_set<int>>> memo(n1 + 1, std::vector<std::unordered_set<int>>(n2 + 1));

        auto dfs = [&](auto& self, int i, int j, int diff) -> bool {
            if (i == n1 && j == n2) return diff == 0;
            if (memo[i][j].count(diff)) return false;

            if (diff < 0 && i < n1 && !std::isdigit(s1[i])) {
                if (self(self, i + 1, j, diff + 1)) return true;
            } else if (diff > 0 && j < n2 && !std::isdigit(s2[j])) {
                if (self(self, i, j + 1, diff - 1)) return true;
            } else if (diff == 0 && i < n1 && j < n2 && !std::isdigit(s1[i]) && !std::isdigit(s2[j])) {
                if (s1[i] == s2[j] && self(self, i + 1, j + 1, 0)) return true;
            }

            if (i < n1 && std::isdigit(s1[i])) {
                int num = 0;
                for (int k = i; k < std::min(i + 3, n1); ++k) {
                    if (!std::isdigit(s1[k])) break;
                    num = num * 10 + (s1[k] - '0');
                    if (self(self, k + 1, j, diff + num)) return true;
                }
            }

            if (j < n2 && std::isdigit(s2[j])) {
                int num = 0;
                for (int k = j; k < std::min(j + 3, n2); ++k) {
                    if (!std::isdigit(s2[k])) break;
                    num = num * 10 + (s2[k] - '0');
                    if (self(self, i, k + 1, diff - num)) return true;
                }
            }

            memo[i][j].insert(diff);
            return false;
        };

        return dfs(dfs, 0, 0, 0);
    }
};

import java.util.HashSet;
import java.util.Set;

class Solution {
    private Set<Integer>[][] memo;

    public boolean possiblyEquals(String s1, String s2) {
        int n1 = s1.length(), n2 = s2.length();
        memo = new HashSet[n1 + 1][n2 + 1];
        for (int i = 0; i <= n1; i++) {
            for (int j = 0; j <= n2; j++) {
                memo[i][j] = new HashSet<>();
            }
        }
        return dfs(0, 0, 0, s1, s2);
    }

    private boolean dfs(int i, int j, int diff, String s1, String s2) {
        int n1 = s1.length(), n2 = s2.length();
        if (i == n1 && j == n2) return diff == 0;
        if (memo[i][j].contains(diff)) return false;

        if (diff < 0 && i < n1 && !Character.isDigit(s1.charAt(i))) {
            if (dfs(i + 1, j, diff + 1, s1, s2)) return true;
        } else if (diff > 0 && j < n2 && !Character.isDigit(s2.charAt(j))) {
            if (dfs(i, j + 1, diff - 1, s1, s2)) return true;
        } else if (diff == 0 && i < n1 && j < n2 && !Character.isDigit(s1.charAt(i)) && !Character.isDigit(s2.charAt(j))) {
            if (s1.charAt(i) == s2.charAt(j) && dfs(i + 1, j + 1, 0, s1, s2)) return true;
        }

        if (i < n1 && Character.isDigit(s1.charAt(i))) {
            int num = 0;
            for (int k = i; k < Math.min(i + 3, n1); k++) {
                if (!Character.isDigit(s1.charAt(k))) break;
                num = num * 10 + (s1.charAt(k) - '0');
                if (dfs(k + 1, j, diff + num, s1, s2)) return true;
            }
        }

        if (j < n2 && Character.isDigit(s2.charAt(j))) {
            int num = 0;
            for (int k = j; k < Math.min(j + 3, n2); k++) {
                if (!Character.isDigit(s2.charAt(k))) break;
                num = num * 10 + (s2.charAt(k) - '0');
                if (dfs(i, k + 1, diff - num, s1, s2)) return true;
            }
        }

        memo[i][j].add(diff);
        return false;
    }
}

