var possiblyEquals = function(s1, s2) {
    const memo = new Map();

    function dfs(i, j, diff) {
        if (i === s1.length && j === s2.length) return diff === 0;
        const key = `${i},${j},${diff}`;
        if (memo.has(key)) return memo.get(key);

        if (diff < 0 && i < s1.length && !/\d/.test(s1[i])) {
            if (dfs(i + 1, j, diff + 1)) {
                memo.set(key, true);
                return true;
            }
        } else if (diff > 0 && j < s2.length && !/\d/.test(s2[j])) {
            if (dfs(i, j + 1, diff - 1)) {
                memo.set(key, true);
                return true;
            }
        } else if (diff === 0 && i < s1.length && j < s2.length && !/\d/.test(s1[i]) && !/\d/.test(s2[j])) {
            if (s1[i] === s2[j] && dfs(i + 1, j + 1, 0)) {
                memo.set(key, true);
                return true;
            }
        }

        if (i < s1.length && /\d/.test(s1[i])) {
            let num = 0;
            for (let k = i; k < Math.min(i + 3, s1.length); k++) {
                if (!/\d/.test(s1[k])) break;
                num = num * 10 + Number(s1[k]);
                if (dfs(k + 1, j, diff + num)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }

        if (j < s2.length && /\d/.test(s2[j])) {
            let num = 0;
            for (let k = j; k < Math.min(j + 3, s2.length); k++) {
                if (!/\d/.test(s2[k])) break;
                num = num * 10 + Number(s2[k]);
                if (dfs(i, k + 1, diff - num)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }

        memo.set(key, false);
        return false;
    }

    return dfs(0, 0, 0);
};
